package com.smarthotel.network;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.URI;import java.net.http.*;import java.util.concurrent.*;
public class HotelApiService { private final ExecutorService pool=Executors.newFixedThreadPool(4); public CompletableFuture<String> fetchTip(){return CompletableFuture.supplyAsync(()->{try{HttpRequest q=HttpRequest.newBuilder(URI.create("https://dummyjson.com/quotes/1")).GET().build();return HttpClient.newHttpClient().send(q,HttpResponse.BodyHandlers.ofString()).body();}catch(Exception e){return "{\"quote\":\"Welcome to Smart Hotel\"}";}},pool);} public String parseQuote(String json)throws Exception{JsonNode n=new ObjectMapper().readTree(json);return n.path("quote").asText("Welcome to Smart Hotel");} public void shutdown(){pool.shutdown();} }
